function token2022Program2() {
  return (client) => {
    return kit.pipe(
      client,
      token2022Program(),
      (c) => kit.extendClient(c, {
        token2022: {
          ...c.token2022,
          instructions: {
            ...c.token2022.instructions,
            batch: (input, config) => programClientCore.addSelfPlanAndSendFunctions(client, getBatchInstruction2(input, config)),
            createMint: (input, config) => programClientCore.addSelfPlanAndSendFunctions(
              client,
              getCreateMintInstructionPlan(
                client,
                { ...input, payer: input.payer ?? client.payer },
                config
              )
            ),
            createToken: (input, config) => programClientCore.addSelfPlanAndSendFunctions(
              client,
              getCreateTokenInstructionPlan(
                client,
                { ...input, payer: input.payer ?? client.payer },
                config
              )
            ),
            mintToATA: (input, config) => programClientCore.addSelfPlanAndSendFunctions(
              client,
              getMintToATAInstructionPlanAsync(
                { ...input, payer: input.payer ?? client.payer },
                config
              )
            ),
            transferToATA: (input, config) => programClientCore.addSelfPlanAndSendFunctions(
              client,
              getTransferToATAInstructionPlanAsync(
                { ...input, payer: input.payer ?? client.payer },
                config
              )
            ),
            transferToATAWithTransferHook: (input, config) => programClientCore.addSelfPlanAndSendFunctions(
              client,
              getTransferToATAWithTransferHookInstructionPlanAsync(
                client,
                { ...input, payer: input.payer ?? client.payer },
                config
              )
            ),
            transferCheckedWithTransferHook: (input, config) => programClientCore.addSelfPlanAndSendFunctions(
              client,
              getTransferCheckedWithTransferHookInstructionAsync(client, input, config)
            )
          }
        }
      })
    );
  };
}
var ONE_IN_BASIS_POINTS = 1e4;
